ALTER TABLE public.hospital_directory ADD COLUMN IF NOT EXISTS pincode text;
CREATE INDEX IF NOT EXISTS hospital_directory_pincode_idx ON public.hospital_directory (pincode);
CREATE INDEX IF NOT EXISTS hospital_directory_name_idx ON public.hospital_directory (name);

ON CONFLICT (external_id) DO UPDATE
 SET pincode = EXCLUDED.pincode,
     address = EXCLUDED.address,
     phone = EXCLUDED.phone,
     emergency_phone = EXCLUDED.emergency_phone,
     verification_status = EXCLUDED.verification_status,
     updated_at = now();